CREATE POLICY "Assignment comments viewable by participants" ON public.assignment_comments FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1    FROM student_assignments sa   WHERE ((sa.id = assignment_comments.assignment_id) AND ((sa.teacher_id = auth.uid()) OR is_parent_of_student(auth.uid(), sa.student_id))))) OR is_super_admin(auth.uid()) OR has_role(auth.uid(), 'csr'::app_role)));
