CREATE POLICY "Users can view employees" ON public.employees FOR SELECT TO authenticated USING ((is_super_admin(auth.uid()) OR has_role(auth.uid(), 'global_csr'::app_role) OR ((has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'csr'::app_role) OR has_role(auth.uid(), 'crm'::app_role)) AND ((center_ids IS NULL) OR (array_length(center_ids, 1) IS NULL) OR (array_length(center_ids, 1) = 0) OR (EXISTS ( SELECT 1    FROM unnest(employees.center_ids) emp_center(emp_center)   WHERE user_has_center_access(auth.uid(), emp_center.emp_center)))))));
