CREATE POLICY "Parents can view their news events" ON public.news_events FOR SELECT TO authenticated USING (((status = 'published'::text) AND ((audience_scope = 'global'::text) OR ((audience_scope = 'learning_center'::text) AND (EXISTS ( SELECT 1    FROM ((enrollments e      JOIN students s ON ((s.id = e.student_id)))      JOIN parents p ON ((p.id = s.parent_id_new)))   WHERE ((p.id = get_parent_id_by_auth_email()) AND (e.center_id = ANY (news_events.center_ids)) AND (e.deleted_at IS NULL))))) OR ((audience_scope = ANY (ARRAY['specific_customers'::text, 'single_customer'::text])) AND (get_parent_id_by_auth_email() = ANY (customer_ids))))));
CREATE POLICY "Anyone can view messages for accessible packages" ON public.package_messages FOR SELECT TO public USING (((EXISTS ( SELECT 1    FROM user_roles   WHERE ((user_roles.user_id = auth.uid()) AND (user_roles.role = ANY (ARRAY['admin'::app_role, 'super_admin'::app_role, 'csr'::app_role, 'global_csr'::app_role]))))) OR (EXISTS ( SELECT 1    FROM custom_packages cp   WHERE ((cp.id = package_messages.package_id) AND (lower(cp.customer_email) = lower((( SELECT users.email            FROM auth.users           WHERE (users.id = auth.uid())))::text)))))));
