CREATE POLICY "CSR can view parents in their scope" ON public.parents FOR SELECT TO authenticated USING ((is_super_admin(auth.uid()) OR has_role(auth.uid(), 'global_csr'::app_role) OR ((has_role(auth.uid(), 'csr'::app_role) OR has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'crm'::app_role)) AND (id IN ( SELECT students.parent_id_new    FROM students   WHERE (students.id IN ( SELECT enrollments.student_id            FROM enrollments           WHERE user_has_center_access(auth.uid(), enrollments.center_id))))))));
CREATE POLICY "Front desk can view parents in their centers" ON public.parents FOR SELECT TO authenticated USING ((has_role(auth.uid(), 'frontdesk'::text) AND ((NOT (EXISTS ( SELECT 1    FROM user_learning_centers   WHERE (user_learning_centers.user_id = auth.uid())))) OR (EXISTS ( SELECT 1    FROM ((students s      JOIN enrollments e ON ((e.student_id = s.id)))      JOIN user_learning_centers ulc ON ((ulc.center_id = e.center_id)))   WHERE ((s.parent_id_new = parents.id) AND (ulc.user_id = auth.uid()) AND (e.deleted_at IS NULL) AND (s.deleted_at IS NULL)))) OR (EXISTS ( SELECT 1    FROM (child_attendance ca      JOIN user_learning_centers ulc ON ((ulc.center_id = ca.learning_center_id)))   WHERE ((ca.parent_id = parents.id) AND (ulc.user_id = auth.uid()))))) AND (deleted_at IS NULL)));
CREATE POLICY "Parents: CSR access by center" ON public.parents FOR ALL TO authenticated USING ((has_role(auth.uid(), 'csr'::app_role) AND ((NOT (EXISTS ( SELECT 1    FROM user_learning_centers   WHERE (user_learning_centers.user_id = auth.uid())))) OR parent_in_user_centers(id, auth.uid()))));
CREATE POLICY "Staff can view parents" ON public.parents FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1    FROM user_roles   WHERE ((user_roles.user_id = auth.uid()) AND (user_roles.role = ANY (ARRAY['staff'::app_role, 'csr'::app_role, 'admin'::app_role, 'super_admin'::app_role, 'global_csr'::app_role, 'crm'::app_role]))))));
CREATE POLICY "Teachers can view parents of their batch students" ON public.parents FOR SELECT TO public USING ((EXISTS ( SELECT 1    FROM ((students s      JOIN batch_students bs ON ((bs.student_id = s.id)))      JOIN batches b ON ((b.id = bs.batch_id)))   WHERE ((s.parent_id_new = parents.id) AND (b.teacher_id = auth.uid()) AND (bs.status = 'active'::text) AND (s.deleted_at IS NULL) AND (parents.deleted_at IS NULL)))));
